SELECT EXISTS
	(
		SELECT mst.cont_nm
		FROM   tblmi_cont_mst AS mst
		WHERE  mst.del_yn = 'N'

				and mst.cont_grp_cd = #{cont_grp_cd}


				and mst.seq != #{seq}


				and mst.CONT_NM = #{cont_nm}

	)

SELECT a.seq , a.ch_tp , a.cont_nm , a.cont_grp_cd , a.use_yn , a.del_yn , a.reg_dt , ifnull(a.upd_dt, a.reg_dt) as upd_dt , a.cont_tp_lst , a.cont_tp_lst_nm , b.cont_tp , c.cd_nm AS cont_tp_nm , b.CONT_SUB , b.CONT_TOP_BODY , b.CONT_BODY , b.send_tp , d.cd_nm AS send_tp_nm , b.send_to , b.send_nm , b.thm_url , b.br_yn , b.sup_yn , a.msg_tp_lst , b.msg_tp , b.kko_img_cd , e.IMG_URL AS kko_image_url , b.kko_img_url , b.kko_BTN_nm , b.KKO_BTN_URL , b.KKO_BTN_URLPC , b.kko_BTN_nm2 , b.KKO_BTN_URL2 , b.KKO_BTN_URLPC2 , b.kko_BTN_nm3 , b.KKO_BTN_URL3 , b.KKO_BTN_URLPC3 , b.kko_BTN_nm4 , b.KKO_BTN_URL4 , b.KKO_BTN_URLPC4 , b.kko_BTN_nm5 , b.KKO_BTN_URL5 , b.KKO_BTN_URLPC5 , b.kko_btn_obj , CONCAT(IFNULL(img_1.img_url,' '),',',IFNULL(img_2.img_url,' '),',',IFNULL(img_3.img_url,' '),',',IFNULL(img_4.img_url,' '),',',IFNULL( img_5.img_url,' '),',',IFNULL(img_6.img_url,' ')) AS IMG_LST , CONCAT(IFNULL(img_1.img_nm,' '), ',' , IFNULL(img_2.img_nm,' '), ',' , IFNULL(img_3.img_nm,' '), ',' , IFNULL(img_4.img_nm,' '), ',' , IFNULL(img_5.img_nm,' '), ',' , IFNULL(img_6.img_nm,' ')) AS IMG_NM_LST , b.RCS_BTN_INS_TP , b.RCS_BTN_CNT , b.RCS_BTN_OBJ , b.RCS_BTN_1 , b.RCS_BTN_TP_1 , b.RCS_BTN_CONT_1 , b.RCS_BTN_2 , b.RCS_BTN_TP_2 , b.RCS_BTN_CONT_2 , b.RCS_BTN_3 , b.RCS_BTN_TP_3 , b.RCS_BTN_CONT_3 , b.RCS_FOOTER , b.key_id , tmpl.tmpl_ext , tmpl.tmpl_ad , tmpl.tmpl_tit , tmpl.tmpl_subtit , tmpl.tmpl_empsize_tp , tmpl.img_seq , tmpl.tmpl_subtit , tmpl.item_highlight_json , tmpl.tmpl_header , tmpl.item_json , tmpl.tmpl_msg_tp , tmpl.button_json FROM ( SELECT mst.seq AS seq , mst.ch_tp AS ch_tp , mst.cont_nm AS cont_nm , mst.cont_grp_cd AS cont_grp_cd , mst.use_yn AS use_yn , mst.del_yn AS del_yn , mst.reg_dt AS reg_dt , mst.upd_dt AS upd_dt , GROUP_CONCAT(lst.SEQ) AS lst_SEQS , Group_concat(lst.cont_tp) AS cont_tp_lst , Group_concat(cd_cont.cd_nm) AS cont_tp_lst_nm , Group_concat(lst.msg_tp) AS msg_tp_lst , CASE WHEN FIND_IN_SET('DMTP04', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP04', Group_concat(lst.cont_tp))), ',', -1) WHEN FIND_IN_SET('DMTP05', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP05', Group_concat(lst.cont_tp))), ',', -1) WHEN FIND_IN_SET('DMTP03', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP03', Group_concat(lst.cont_tp))), ',', -1) WHEN FIND_IN_SET('DMTP02', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP02', Group_concat(lst.cont_tp))), ',', -1) ELSE lst.SEQ END AS lst_seq , IF(Find_in_set('DMTP05', Group_concat(lst.cont_tp)),lst.KEY_ID,'') AS key_id FROM tblmi_cont_mst AS mst LEFT JOIN tblmi_cont_lst AS lst ON lst.cont_cd = mst.seq AND lst.USE_YN = 'Y' INNER JOIN tblmi_comm_cd AS cd_cont ON lst.cont_tp = cd_cont.cd_id
and mst.del_yn = #{del_yn}
and mst.use_yn = #{use_yn}
and mst.cont_grp_cd = #{cont_grp_cd}
and mst.ch_tp = #{ch_tp}
and mst.CONT_NM like concat('%', #{cont_nm}, '%')
and lst.cont_sub like concat('%', #{cont_sub}, '%')
and mst.cont_grp_cd = #{cont_grp_cd}
GROUP BY mst.seq ORDER BY mst.reg_dt DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}
) AS a INNER JOIN tblmi_cont_lst AS b ON a.lst_seq = b.SEQ INNER JOIN tblmi_comm_cd AS c ON b.cont_tp = c.cd_id INNER JOIN tblmi_comm_cd AS d ON b.send_tp = d.cd_id LEFT JOIN tblmi_cont_img AS e ON b.kko_img_cd = e.seq LEFT JOIN tblmi_cont_img AS img_1 ON b.IMG_CD_1 = img_1.seq LEFT JOIN tblmi_cont_img AS img_2 ON b.IMG_CD_2 = img_2.seq LEFT JOIN tblmi_cont_img AS img_3 ON b.IMG_CD_3 = img_3.seq LEFT JOIN tblmi_cont_img AS img_4 ON b.IMG_CD_4 = img_4.seq LEFT JOIN tblmi_cont_img AS img_5 ON b.IMG_CD_5 = img_5.seq LEFT JOIN tblmi_cont_img AS img_6 ON b.IMG_CD_6 = img_6.seq LEFT JOIN tblmi_kko_at_tmpl AS tmpl ON a.key_id = tmpl.tmpl_cd

SELECT COUNT(mseq) FROM( SELECT m.seq AS mseq ,m.CH_TP ,m.cont_nm ,l.* FROM tblmi_cont_mst m INNER JOIN tblmi_cont_lst l ON m.SEQ = l.CONT_CD WHERE DEL_YN = 'N'
AND m.ch_tp = #{ch_tp}
AND m.cont_nm like concat ('%',#{cont_nm},'%')
AND m.cont_grp_cd = #{cont_grp_cd}
AND m.use_yn = #{use_yn}
AND m.del_yn = #{del_yn}
AND l.cont_sub like concat ('%',#{cont_sub},'%')
GROUP BY mseq )AS a

SELECT *
FROM TBLMI_CONT_IMG AS img
LEFT JOIN TBLMI_COMM_CD AS chcd
	ON chcd.cd_id = img.ch_tp
WHERE  img.del_yn = 'N'

		and img.USR_GRP_CD = #{usr_grp_cd}


		and img.SEQ = #{seq}


		and img.img_nm like concat ('%',#{img_nm},'%')




				and img.ch_tp in ('IMGTP09','IMGTP10')


				and img.ch_tp in ('IMGTP03','IMGTP11')


				and img.ch_tp = #{ch_tp}








						and img.REG_DT = #{reg_dt}


						and (img.REG_DT >= #{reg_dt} and img.REG_DT  <  #{reg_dt_range})




				and img.REG_DT = #{reg_dt}



order by img.REG_DT DESC

	LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

SELECT Count(*)
FROM TBLMI_CONT_IMG AS img
	LEFT JOIN TBLMI_COMM_CD AS chcd
		ON chcd.cd_id = img.ch_tp
WHERE  img.del_yn = 'N'

		and img.USR_GRP_CD = #{usr_grp_cd}


		and img.SEQ = #{seq}




				and img.ch_tp in ('IMGTP09','IMGTP10')


				and img.ch_tp in ('IMGTP03','IMGTP11')


				and img.ch_tp = #{ch_tp}




		and img.img_nm like concat ('%',#{img_nm},'%')






						and img.REG_DT = #{reg_dt}


						and (img.REG_DT >= #{reg_dt} and img.REG_DT  <  #{reg_dt_range})




				and img.REG_DT = #{reg_dt}

