SELECT Count(*)
FROM   TBLMI_CONT_MST AS mst
	LEFT JOIN TBLMI_CONT_LST AS lst
		ON lst.cont_cd = mst.seq

	mst.DEL_YN = 'N'

		and mst.use_yn = #{use_yn}


		and mst.cont_grp_cd = #{cont_grp_cd}


		and mst.ch_tp = #{ch_tp}


		and lst.cont_tp = #{cont_tp}


		and lst.cont_sub LIKE CONCAT('%',#{cont_sub},'%')


		and mst.seq = #{seq}


		and mst.CONT_NM LIKE CONCAT('%',#{cont_nm},'%')

SELECT mst.seq AS seq ,mst.ch_tp AS ch_tp ,mst.cont_nm AS cont_nm ,mst.cont_grp_cd AS cont_grp_cd ,mst.use_yn AS use_yn ,mst.del_yn AS del_yn ,mst.reg_id AS reg_id ,mst.reg_dt AS reg_dt ,mst.upd_id AS upd_id ,mst.upd_dt AS upd_dt ,lst.seq AS list_seq ,lst.cont_cd AS cont_cd ,lst.cont_tp AS cont_tp ,lst.cont_sub AS cont_sub ,lst.cont_top_body AS cont_top_body ,lst.cont_body AS cont_body ,lst.send_tp AS send_tp , cd.cd_nm AS send_tp_nm ,lst.send_to AS send_to ,Concat(setLst.list_nm, '(', setLst.list_val, ')') AS send_nm ,lst.thm_url AS thm_url ,lst.br_yn AS br_yn ,lst.sup_yn AS sup_yn ,lst.msg_tp AS msg_yp ,lst.use_yn AS list_use_yn ,lst.reg_id AS LIST_REG_ID ,lst.reg_dt AS list_reg_dt ,lst.upd_id AS list_upd_id ,lst.upd_dt AS list_upd_dt FROM tblmi_cont_mst AS mst LEFT JOIN tblmi_cont_lst AS lst ON lst.cont_cd = mst.seq LEFT JOIN tblmi_set_lst AS setLst ON lst.send_to = setLst.seq INNER JOIN tblmi_comm_cd AS cd ON lst.send_tp = cd.cd_id
mst.DEL_YN = 'N'
and mst.use_yn = #{use_yn}
and mst.cont_grp_cd = #{cont_grp_cd}
and mst.ch_tp = #{ch_tp}
and lst.cont_tp = #{cont_tp}
and lst.cont_sub LIKE CONCAT('%',#{cont_sub},'%')
and mst.seq = #{seq}
and mst.CONT_NM LIKE CONCAT('%',#{cont_nm},'%')
and mst.REG_DT = #{reg_dt}
and (mst.REG_DT >= #{reg_dt} and mst.REG_DT < #{reg_dt_range})
and mst.REG_DT = #{reg_dt}
order by mst.REG_DT DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

SELECT mst.seq AS seq ,mst.ch_tp AS ch_tp ,mst.cont_nm AS cont_nm ,mst.cont_grp_cd AS cont_grp_cd ,mst.use_yn AS use_yn ,mst.del_yn AS del_yn ,mst.reg_id AS reg_id ,mst.reg_dt AS reg_dt ,mst.upd_id AS upd_id ,mst.upd_dt AS upd_dt ,lst.seq AS list_seq ,lst.cont_cd AS cont_cd ,lst.cont_tp AS cont_tp ,lst.cont_sub AS cont_sub ,lst.cont_top_body AS cont_top_body ,lst.cont_body AS cont_body ,lst.send_tp AS send_tp , cd.cd_nm AS send_tp_nm ,lst.send_to AS send_to ,Concat(setLst.list_nm, '(', setLst.list_val, ')') AS send_nm ,lst.thm_url AS thm_url ,lst.br_yn AS br_yn ,lst.sup_yn AS sup_yn ,lst.msg_tp AS msg_yp ,lst.use_yn AS list_use_yn ,lst.reg_id AS LIST_REG_ID ,lst.reg_dt AS list_reg_dt ,lst.upd_id AS list_upd_id ,lst.upd_dt AS list_upd_dt FROM tblmi_cont_mst AS mst LEFT JOIN tblmi_cont_lst AS lst ON lst.cont_cd = mst.seq LEFT JOIN tblmi_set_lst AS setLst ON lst.send_to = setLst.seq INNER JOIN tblmi_comm_cd AS cd on lst.send_tp = cd.cd_id
mst.DEL_YN = 'N'
