SELECT m.* , l.seq AS list_seq , l.cont_cd AS cont_cd , l.cont_tp AS cont_tp , l.cont_sub AS cont_sub , l.cont_body AS cont_body , l.send_to AS send_to , l.send_tp AS send_tp , l.msg_tp AS msg_tp , l.kko_img_cd AS kko_img_cd , l.kko_img_url AS kko_img_url , l.kko_btn_nm AS kko_btn_nm , l.kko_btn_url AS kko_btn_url , l.kko_btn_urlpc AS kko_btn_urlpc , l.kko_btn_nm2 AS kko_btn_nm2 , l.kko_btn_url2 AS kko_btn_url2 , l.kko_btn_urlpc2 AS kko_btn_urlpc2 , l.kko_btn_nm3 AS kko_btn_nm3 , l.kko_btn_url3 AS kko_btn_url3 , l.kko_btn_urlpc3 AS kko_btn_urlpc3 , l.kko_btn_nm4 AS kko_btn_nm4 , l.kko_btn_url4 AS kko_btn_url4 , l.kko_btn_urlpc4 AS kko_btn_urlpc4 , l.kko_btn_nm5 AS kko_btn_nm5 , l.kko_btn_url5 AS kko_btn_url5 , l.kko_btn_urlpc5 AS kko_btn_urlpc5 , l.img_cd_1 AS img_cd_1 , l.img_cd_2 AS img_cd_2 , l.img_cd_3 AS img_cd_3 , l.img_cd_4 AS img_cd_4 , l.img_cd_5 AS img_cd_5 , l.img_cd_6 AS img_cd_6 , l.rcs_btn_1 AS rcs_btn_1 , l.rcs_btn_tp_1 AS rcs_btn_tp_1 , l.rcs_btn_cont_1 AS rcs_btn_cont_1 , l.rcs_btn_2 AS rcs_btn_2 , l.rcs_btn_tp_2 AS rcs_btn_tp_2 , l.rcs_btn_cont_2 AS rcs_btn_cont_2 , l.rcs_btn_3 AS rcs_btn_3 , l.rcs_btn_tp_3 AS rcs_btn_tp_3 , l.rcs_btn_cont_3 AS rcs_btn_cont_3 , l.use_yn AS list_use_yn FROM TBLMI_CONT_MST m INNER JOIN TBLMI_CONT_LST l ON m.seq = l.cont_cd WHERE l.use_yn = 'Y' AND m.del_yn = 'N'
